* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, sans-serif; color: #263342; background: #e8f1ef; }
body { min-width: 360px; min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background-color: #e8f1ef; background-image: radial-gradient(#c8ded8 1.5px, transparent 1.5px); background-size: 20px 20px; }
.shop { width: min(100%, 620px); padding: 32px; border: 3px solid #263342; border-radius: 12px; background: #fffdf5; box-shadow: 8px 8px 0 #263342; }
.shop-header { text-align: center; }
.eyebrow { margin: 0 0 8px; color: #d36a50; font-size: 16px; font-weight: 800; letter-spacing: .08em; }
h1 { margin: 0; font-size: clamp(36px, 9vw, 52px); line-height: 1.1; }
.subtitle { margin: 10px 0 24px; color: #596675; font-size: 17px; }
.sales { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 28px; padding: 16px 20px; border: 2px solid #263342; border-radius: 8px; background: #d9efe6; font-size: 18px; font-weight: 700; }
.sales strong { color: #23735d; font-size: 25px; font-variant-numeric: tabular-nums; }
.section-title { margin: 0 0 12px; font-size: 15px; letter-spacing: .08em; }
.inventory { display: grid; gap: 12px; }
.item { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 10px 16px; padding: 15px; border: 2px solid #d5ddd8; border-radius: 8px; background: white; }
.item-info { min-width: 0; }
.item-name { margin: 0; font-size: 18px; }
.item-meta { margin: 4px 0 0; color: #596675; font-size: 16px; }
.item-stock { margin-top: 7px; color: #23735d; font-size: 15px; font-weight: 700; }
.item-stock.sold-out { color: #b34f3b; }
.item-actions { display: flex; flex-wrap: wrap; justify-content: end; gap: 8px; }
button { min-height: 44px; padding: 9px 13px; border: 2px solid #263342; border-radius: 6px; background: #f5c75e; color: #263342; font: inherit; font-size: 16px; font-weight: 750; cursor: pointer; transition: transform .12s, background-color .12s, box-shadow .12s; }
button:hover:not(:disabled) { background: #ffd978; transform: translateY(-2px); box-shadow: 0 3px 0 #263342; }
button:active:not(:disabled) { transform: translateY(1px); box-shadow: none; }
button:focus-visible { outline: 3px solid #23735d; outline-offset: 3px; }
button.restock { background: #d9efe6; }
button.restock:hover:not(:disabled) { background: #bfe3d3; }
button:disabled { border-color: #c6cbc8; background: #eceeeb; color: #747d78; cursor: not-allowed; }
footer { margin-top: 24px; text-align: center; color: #596675; font-size: 16px; }
footer span { color: #d36a50; }
@media (max-width: 480px) { body { padding: 20px 12px; } .shop { padding: 22px 16px; } .item { grid-template-columns: 1fr; } .item-actions { justify-content: stretch; } .item-actions button { flex: 1; } }

const items = [
  { id: 'star-plush', name: 'Star Plush', price: 12, stock: 4 },
  { id: 'berry-soda', name: 'Berry Soda', price: 3, stock: 8 },
  { id: 'moon-cookie', name: 'Moon Cookie', price: 5, stock: 3 },
  { id: 'tiny-plant', name: 'Tiny Plant', price: 9, stock: 6 },
  { id: 'pixel-pin', name: 'Pixel Pin', price: 4, stock: 2 }
];
let todaysSales = 0;
const inventory = document.querySelector('#inventory');
const salesTotal = document.querySelector('#sales-total');
const money = amount => `$${amount.toFixed(2)}`;

function render() {
  inventory.replaceChildren(...items.map(item => {
    const card = document.createElement('article');
    card.className = 'item';
    const info = document.createElement('div');
    info.className = 'item-info';
    const name = document.createElement('h3');
    name.className = 'item-name';
    name.textContent = item.name;
    const price = document.createElement('p');
    price.className = 'item-meta';
    price.textContent = `${money(item.price)} each`;
    const stock = document.createElement('div');
    stock.className = `item-stock${item.stock === 0 ? ' sold-out' : ''}`;
    stock.textContent = item.stock === 0 ? 'Sold out' : `In stock: ${item.stock}`;
    info.append(name, price, stock);
    const actions = document.createElement('div');
    actions.className = 'item-actions';
    const sell = document.createElement('button');
    sell.type = 'button';
    sell.textContent = 'Sell';
    sell.setAttribute('aria-label', `Sell ${item.name}`);
    sell.disabled = item.stock === 0;
    sell.addEventListener('click', () => {
      if (item.stock === 0) return;
      item.stock -= 1;
      todaysSales += item.price;
      render();
    });
    const restock = document.createElement('button');
    restock.type = 'button';
    restock.className = 'restock';
    restock.textContent = 'Restock +10';
    restock.setAttribute('aria-label', `Restock ${item.name} by 10`);
    restock.addEventListener('click', () => {
      item.stock += 10;
      render();
    });
    actions.append(sell, restock);
    card.append(info, actions);
    return card;
  }));
  salesTotal.textContent = money(todaysSales);
}

render();
